static void unescape_tag(char *tag)
{
	char *tmp;

	if (tag == NULL)
		return;

	tmp = tag;
	for (; *tmp != '\0'; tmp++, tag++) {
		if (*tmp == '\\') {
			tmp++;
			switch (*tmp) {
			case ':':
				*tag = ';';
				break;
			case 'n':
				*tag = '\n';
				break;
			case 'r':
				*tag = '\r';
				break;
			case 's':
				*tag = ' ';
				break;
			default:
				*tag = *tmp;
				break;
			}
		} else {
			*tag = *tmp;
		}
	}
	*tag = '\0';
}

